func resolveConflictTarget(binding *masterBindingRuntime, colTypes map[string]string) string {
	if binding != nil && len(binding.TransformSpec) > 0 {
		pk := parsePKFromSpec(binding.TransformSpec)
		if pk != "" && pk != "_gpay_id" && ddlIdentRe.MatchString(pk) {
			if colTypes == nil {
				return pk
			}
			if _, ok := colTypes[pk]; ok {
				return pk
			}
		}
	}
	return "_gpay_id"
}

// isMasterPKMappedFromSourcePK verifies via mapping_rule_master that the Master PK column
// resolved from transform_spec.pk maps from the source primary key (binding.SourcePK or _source_id).
func isMasterPKMappedFromSourcePK(binding *masterBindingRuntime, rules []mappingRuleRow, pkCol string) bool {
	if binding == nil || pkCol == "" || pkCol == "_gpay_id" || binding.TransformType == "flatten" {
		return false
	}
	for _, r := range rules {
		if r.TargetColumn == pkCol {
			srcField := strings.TrimSpace(r.SourceField)
			if srcField == "" {
				srcField = r.TargetColumn
			}
			if srcField == "_source_id" {
				return true
			}
			if binding.SourcePK != "" {
				return srcField == binding.SourcePK
			}
			return srcField == pkCol
		}
	}
	if len(rules) == 0 {
		return binding.SourcePK == "" || pkCol == binding.SourcePK
	}
	return false
}

